{
  "claims": [
    {
      "claim_text": "Redis replication is non-blocking on the master side.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 explicitly states that Redis replication is non-blocking on the master side.",
      "citations": [
        {
          "index": 0,
          "quote": "Redis replication is non-blocking on the master side."
        }
      ]
    },
    {
      "claim_text": "After the initial sync a replica keeps serving queries from the old dataset while it loads the new one.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 says the replica can serve queries from the old dataset during the initial synchronization, but after the initial sync the old dataset must be deleted and the new one loaded, and the replica blocks incoming connections during that window.",
      "citations": [
        {
          "index": 0,
          "quote": "However, after the initial sync, the old dataset must be deleted and the new one must be loaded. The replica will block incoming connections during this brief window"
        }
      ]
    },
    {
      "claim_text": "Replicas that reconnect use PSYNC.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states that when replicas connect to masters they use the PSYNC command.",
      "citations": [
        {
          "index": 1,
          "quote": "When replicas connect to masters, they use the `PSYNC` command"
        }
      ]
    },
    {
      "claim_text": "A full resynchronization only happens when the replica's replication ID is unknown to the master.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 1 gives two conditions for a full resync: insufficient backlog in master buffers OR unknown replication ID. The claim says 'only' the unknown ID case, omitting the backlog condition.",
      "citations": [
        {
          "index": 1,
          "quote": "However if there is not enough *backlog* in the master buffers, or if the replica is referring to an history (replication ID) which is no longer known, then a full resynchronization happens"
        }
      ]
    },
    {
      "claim_text": "After a failover the promoted replica keeps its replication ID.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 2 says the promoted replica sets its secondary ID to its main ID and later selects a new random replication ID; passage 3 explains it needs to change its replication ID after failover.",
      "citations": [
        {
          "index": 2,
          "quote": "Later it will select a new random replication ID, because a new history begins."
        },
        {
          "index": 3,
          "quote": "In case you wonder why a replica promoted to master needs to change its replication ID after a failover"
        }
      ]
    },
    {
      "claim_text": "The old master's replicas can still continue with a partial sync after a failover.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 and passage 8 state that after a failover, replicas connecting to the newly promoted master don't have to perform a full sync and can partially resynchronize using the old replication ID.",
      "citations": [
        {
          "index": 2,
          "quote": "In short this means that after a failover, replicas connecting to the newly promoted master don't have to perform a full sync."
        },
        {
          "index": 8,
          "quote": "Since Redis 4.0, when an instance is promoted to master after a failover, it will still be able to perform a partial resynchronization with the replicas of the old master."
        }
      ]
    },
    {
      "claim_text": "Partial sync after failover has been possible since Redis 4.0.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 explicitly states this capability exists since Redis 4.0.",
      "citations": [
        {
          "index": 8,
          "quote": "Since Redis 4.0, when an instance is promoted to master after a failover, it will still be able to perform a partial resynchronization with the replicas of the old master."
        }
      ]
    },
    {
      "claim_text": "Diskless replication, first available in Redis 2.6.18, sends the RDB to replicas without using the disk as intermediate storage.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 says Redis version 2.8.18 is the first version to support diskless replication, not 2.6.18. The mechanism description is correct, but the version is wrong.",
      "citations": [
        {
          "index": 4,
          "quote": "Redis version 2.8.18 is the first version to have support for diskless replication."
        }
      ]
    },
    {
      "claim_text": "Read-only replicas reject all write commands.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states read-only replicas will reject all write commands.",
      "citations": [
        {
          "index": 5,
          "quote": "Read-only replicas will reject all write commands"
        }
      ]
    },
    {
      "claim_text": "Read-only replicas are safe to expose to untrusted networks.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 5 explicitly says the feature is not intended to expose a replica to the internet or untrusted networks because administrative commands like DEBUG or CONFIG are still enabled.",
      "citations": [
        {
          "index": 5,
          "quote": "This does not mean that the feature is intended to expose a replica instance to the internet or more generally to a network where untrusted clients exist, because administrative commands like `DEBUG` or `CONFIG` are still enabled."
        }
      ]
    },
    {
      "claim_text": "Writes made to a writable replica are discarded when the replica and the master resync.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states writes to a replica will be discarded if the replica and the master resync or if the replica is restarted.",
      "citations": [
        {
          "index": 6,
          "quote": "While writes to a replica will be discarded if the replica and the master resync or if the replica is restarted"
        }
      ]
    },
    {
      "claim_text": "Before Redis 4.0, writable replicas could not expire keys with a TTL.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states before version 4.0, writable replicas were incapable of expiring keys with a time to live set.",
      "citations": [
        {
          "index": 7,
          "quote": "Before version 4.0, writable replicas were incapable of expiring keys with a time to live set."
        }
      ]
    },
    {
      "claim_text": "A replica restarted from its AOF file can still be partially resynchronized.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 9 explicitly states it is not possible to partially sync a replica that restarted via the AOF file.",
      "citations": [
        {
          "index": 9,
          "quote": "It is not possible to partially sync a replica that restarted via the AOF file."
        }
      ]
    }
  ]
}
